// FindTelegramRSAKey returns the first matching new key, or an old key
// when allowOld is true or no new key matches.
func FindTelegramRSAKey(fingerprints []uint64, allowOld bool) (*rsa.PublicKey, uint64, bool) {
	for _, fingerprint := range fingerprints {
		for index := range telegramRSAKeys {
			key := &telegramRSAKeys[index]
			if key.fingerprint == fingerprint && (allowOld || !key.old) {
				return key.publicKey(), fingerprint, true
			}
		}
	}
	if !allowOld {
		return FindTelegramRSAKey(fingerprints, true)
	}
	return nil, 0, false
}

func (key *telegramRSAKey) publicKey() *rsa.PublicKey {
	return &rsa.PublicKey{N: new(big.Int).SetBytes(key.modulus[:]), E: int(key.exponent[0])<<16 | int(key.exponent[1])<<8 | int(key.exponent[2])}
}
